INSERT INTO challenges (id,slug,type,stage,title,summary,body,media,location,lat,lng,tags,author_id,created_at,last_activity_at,seed_actions) VALUES ('ch_milk_cooling_loss','milk-cooling-loss','problem','ideas','This farmer loses a third of his milk to the afternoon heat','No grid power at the collection point. Milk sits at 34C for four hours before the truck comes.',NULL,'[{"kind":"image","url":"/seed/milk-cooling-loss.svg","w":1200,"h":900,"tint":"#c9b89a","alt":"Milk cans standing in the sun"}]','Chiang Mai, Thailand',18.79,98.98,'["agriculture","cooling","off-grid"]','p_niran','2026-08-20 08:19:33','2026-09-09 08:19:33','{"have_problem":4712,"want_this":890,"have_idea":143,"can_help":34,"will_test":12,"building_this":3,"follow":1205}');
