INSERT INTO updates (id,challenge_id,author_id,stage,body,media,created_at) VALUES ('up_1','ch_milk_cooling_loss','p_dave','understand','Ran the numbers on evaporative cooling for this humidity. 61% RH at 34C gives about 6C of drop - not enough alone, but it halves the load on anything we add.','[]','2026-09-06 08:19:33');
INSERT INTO updates (id,challenge_id,author_id,stage,body,media,created_at) VALUES ('up_2','ch_milk_cooling_loss','p_arun','ideas','Solar thermal absorption chiller is overkill here. A 200W panel plus a compressor and a phase-change buffer would hold 4C through the afternoon for around $180 in parts.','[]','2026-09-09 08:19:33');
INSERT INTO challenges (id,slug,type,stage,title,summary,body,media,location,lat,lng,tags,author_id,created_at,last_activity_at,seed_actions) VALUES ('ch_drone_compute_mesh','drone-compute-mesh','idea','understand','Could compute move around a city on autonomous drones?','GPUs are idle at night in one district and saturated in another. What if the hardware flew to the demand?',NULL,'[{"kind":"image","url":"/seed/drone-compute-mesh.svg","w":1200,"h":900,"tint":"#8fa3b8","alt":"A drone carrying a compute unit over a city"}]',NULL,NULL,NULL,'["compute","drones","infrastructure"]','p_lucas','2026-08-07 08:19:33','2026-09-07 08:19:33','{"have_problem":61,"want_this":2204,"have_idea":412,"can_help":88,"will_test":9,"building_this":6,"follow":3102}');
