INSERT INTO updates (id,challenge_id,author_id,stage,body,media,created_at) VALUES ('up_3','ch_drone_compute_mesh','p_tomas','understand','Battery math is brutal. Carrying an H100 and its cooling means you spend more energy flying it than you save. It only works if the payload is under about 2kg - so edge inference silicon, not datacentre parts.','[]','2026-09-07 08:19:33');
INSERT INTO challenges (id,slug,type,stage,title,summary,body,media,location,lat,lng,tags,author_id,created_at,last_activity_at,seed_actions) VALUES ('ch_rainy_season_mosquitoes','rainy-season-mosquitoes','problem','understand','This village gets a strange mosquito surge for six weeks every rainy season','It starts nine days after the first heavy rain, every year, and stops as abruptly as it starts.',NULL,'[{"kind":"image","url":"/seed/rainy-season-mosquitoes.svg","w":1200,"h":900,"tint":"#7d8f6a","alt":"Rain falling into standing water with mosquitoes above it"}]','Cross River, Nigeria',5.87,8.6,'["health","water","seasonal"]','p_aisha','2026-08-29 08:19:33','2026-09-08 08:19:33','{"have_problem":1840,"want_this":620,"have_idea":97,"can_help":41,"will_test":23,"building_this":1,"follow":890}');
