INSERT INTO updates (id,challenge_id,author_id,stage,body,media,created_at) VALUES ('up_4','ch_rainy_season_mosquitoes','p_aisha','understand','Nine days matches the Aedes egg-to-adult cycle almost exactly. The eggs are already there, laid dry, waiting for water. That means the intervention window is before the rain, not after.','[]','2026-09-08 08:19:33');
INSERT INTO challenges (id,slug,type,stage,title,summary,body,media,location,lat,lng,tags,author_id,created_at,last_activity_at,seed_actions) VALUES ('ch_bedroom_8c_hotter','bedroom-8c-hotter','problem','ideas','My bedroom runs 8C hotter than the rest of the apartment','Same building, same floor, same size. Thermal camera shows the wall glowing after sunset.',NULL,'[{"kind":"image","url":"/seed/bedroom-8c-hotter.svg","w":1200,"h":900,"tint":"#b8785f","alt":"One wall of a room radiating stored heat"}]','Palermo, Italy',38.12,13.36,'["housing","thermal","cheap-fix"]','p_sofia','2026-09-02 08:19:33','2026-09-09 08:19:33','{"have_problem":2960,"want_this":410,"have_idea":268,"can_help":52,"will_test":31,"building_this":4,"follow":1120}');
