INSERT INTO updates (id,challenge_id,author_id,stage,body,media,created_at) VALUES ('up_5','ch_bedroom_8c_hotter','p_ingrid','ideas','That is a thermal mass problem, not an insulation problem. The wall is charging all day and discharging into the room at night. External shading beats anything you do on the inside - and it is a $40 fix.','[]','2026-09-09 08:19:33');
