INSERT INTO updates (id,challenge_id,author_id,stage,body,media,created_at) VALUES ('up_6','ch_catch_spoils_before_shore','p_mei','build','Sourced the parts for the insulated box version. 40mm PU panel, reflective outer skin, $23 a unit at ten pieces.','[]','2026-09-03 08:19:33');
INSERT INTO updates (id,challenge_id,author_id,stage,body,media,created_at) VALUES ('up_7','ch_catch_spoils_before_shore','p_arun','test','Two boats ran it for a week. Catch temperature at dock was 11C against 24C in the control boat. One box leaked at the lid seam - fixing the gasket and going again.','[]','2026-09-06 08:19:33');
